// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ChangeLocalEmail Change the signed-in User's sign-in address.
	// (POST /auth/local/change-email)
	ChangeLocalEmail(ctx context.Context, request ChangeLocalEmailRequestObject) (ChangeLocalEmailResponseObject, error)
	// ChangeLocalPassword Change the signed-in User's password.
	// (POST /auth/local/change-password)
	ChangeLocalPassword(ctx context.Context, request ChangeLocalPasswordRequestObject) (ChangeLocalPasswordResponseObject, error)
	// LocalLogin Exchange email and password for a server-side session.
	// (POST /auth/local/login)
	LocalLogin(ctx context.Context, request LocalLoginRequestObject) (LocalLoginResponseObject, error)
	// LocalRegister Register a credential and open an onboarding handshake.
	// (POST /auth/local/register)
	LocalRegister(ctx context.Context, request LocalRegisterRequestObject) (LocalRegisterResponseObject, error)
	// Logout Destroy the current server-side session.
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// GetAuthMethods Which identity providers this instance has enabled.
	// (GET /auth/methods)
	GetAuthMethods(ctx context.Context, request GetAuthMethodsRequestObject) (GetAuthMethodsResponseObject, error)
	// GetBudget The Household's Budget for the current Budget Period.
	// (GET /budget)
	GetBudget(ctx context.Context, request GetBudgetRequestObject) (GetBudgetResponseObject, error)
	// UpdateBudget Change the Household's Budget for the current Budget Period.
	// (PATCH /budget)
	UpdateBudget(ctx context.Context, request UpdateBudgetRequestObject) (UpdateBudgetResponseObject, error)
	// GetHealth Liveness and readiness of this instance.
	// (GET /health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// UpdateHousehold Change the caller's Household settings.
	// (PATCH /household)
	UpdateHousehold(ctx context.Context, request UpdateHouseholdRequestObject) (UpdateHouseholdResponseObject, error)
	// GetMe The signed-in User and their Household's settings.
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// UpdateMe Change the signed-in User's own settings.
	// (PATCH /me)
	UpdateMe(ctx context.Context, request UpdateMeRequestObject) (UpdateMeResponseObject, error)
	// CommitOnboardingChoice Commit the gate's choice, creating the account.
	// (POST /onboarding/choice)
	CommitOnboardingChoice(ctx context.Context, request CommitOnboardingChoiceRequestObject) (CommitOnboardingChoiceResponseObject, error)
	// GetOnboardingOptions What the gate offers the holder of a handshake.
	// (GET /onboarding/options)
	GetOnboardingOptions(ctx context.Context, request GetOnboardingOptionsRequestObject) (GetOnboardingOptionsResponseObject, error)
	// ListPockets The caller's Household's Pockets.
	// (GET /pockets)
	ListPockets(ctx context.Context, request ListPocketsRequestObject) (ListPocketsResponseObject, error)
	// CreatePocket Create a Pocket.
	// (POST /pockets)
	CreatePocket(ctx context.Context, request CreatePocketRequestObject) (CreatePocketResponseObject, error)
	// DeletePocket Delete a Pocket.
	// (DELETE /pockets/{id})
	DeletePocket(ctx context.Context, request DeletePocketRequestObject) (DeletePocketResponseObject, error)
	// UpdatePocket Rename, deactivate or reactivate a Pocket.
	// (PATCH /pockets/{id})
	UpdatePocket(ctx context.Context, request UpdatePocketRequestObject) (UpdatePocketResponseObject, error)
	// RestorePocket Restore a deleted Pocket.
	// (POST /pockets/{id}/restore)
	RestorePocket(ctx context.Context, request RestorePocketRequestObject) (RestorePocketResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

